changeSet.sql:
UPDATE payment_attempts SET provider = 'MANUAL', status = 'FAILED', failure_code = 'PAYMENT_PROVIDER_RETIRED', failure_reason = 'The previous payment provider is no longer supported', completed_at = COALESCE(completed_at, CURRENT_TIMESTAMP) WHERE provider NOT IN ('VIETQR', 'MANUAL') AND status IN ('CREATED', 'REDIRECT_READY', 'PENDING');
UPDATE payment_attempts SET provider = 'MANUAL' WHERE provider NOT IN ('VIETQR', 'MANUAL');
UPDATE payment_attempts SET method = 'BANK_TRANSFER' WHERE method NOT IN ('BANK_TRANSFER', 'CASH');
